#include <stdint.h>

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif

#define RCC_BASE_ADDRR 0x40023800UL
#define RCC_CLK_CONFG_REG_OFFSET 0x08UL
#define RCC_CLK_COFG_REG ( RCC_BASE_ADDRR + RCC_CLK_CONFG_REG_OFFSET )

#define RCC_AHB1_ENR_OFFSET 0x30UL
#define RCC_AHB1_ENR_REG ( RCC_BASE_ADDRR + RCC_AHB1_ENR_OFFSET )

#define GPIOA_BASE_ADDR 0x40020000UL
#define GPIOA_MODE_REG_OFFSET 0x0UL
#define GPIOA_ALTERNATE_FUNCTION_HIGH_REG_OFFSET 0x24UL


int main(void)
{
	volatile uint32_t *rcc_clk_confg_reg = (volatile uint32_t*) RCC_CLK_COFG_REG;
	volatile uint32_t *rcc_ahb1_enr_reg = (volatile uint32_t*) RCC_AHB1_ENR_REG;
	volatile uint32_t *gpioa_mode_reg = (volatile uint32_t*) (GPIOA_BASE_ADDR + 0x0);
	volatile uint32_t *gpioa_alternate_function_reg = (volatile uint32_t*) (GPIOA_BASE_ADDR + GPIOA_ALTERNATE_FUNCTION_HIGH_REG_OFFSET);

	*rcc_clk_confg_reg &= ~(0x3 << 21); //clear 21 and 22 bit positions and enable MCO1 (HSI)

	*rcc_clk_confg_reg |= (1 << 25);
	*rcc_clk_confg_reg |= (1 << 26);

	*rcc_ahb1_enr_reg |= 1; //enable RCC for GPIOA port

	*gpioa_mode_reg &= ~(0x3 << 16); //clear

	*gpioa_mode_reg |= (2 << 16); //set mode for PA8 as Alternate function mode

	*gpioa_alternate_function_reg &= ~(0xf << 0); //clear

	*gpioa_alternate_function_reg |= (0 << 0); // set AF0 for PA8

    /* Loop forever */
	for(;;);
}
